use super::*;
use super::super::setup::tests::{network,Reply};
use super::super::tests::{release_case,MemoryStore};
fn fixture()->Core<MemoryStore>{let(mut c,_,_)=release_case();c.open_browser=false;let room=c.room.as_mut().unwrap();room.revision=Some(1);room.config=Some(wire::Config{seed:Some(424242),seed_policy:Some("shared-fixed".into()),randomize_loot:Some(false),mode:Some("core".into()),required_capabilities:Some(vec![]),settings:Some(vec![]),..Default::default()});c}
#[test]fn ux1_actual_native_start_preflight_lost_reply_exposes_original_pending_and_retries_exactly(){tauri::async_runtime::block_on(async{
 let(mut c,p)=super::super::start::tests::fixture();let room=c.room.clone().unwrap();let config=room.config_revision.unwrap();let mut running=room.clone();running.state=Some("running".into());
 let(origin,server)=network(vec![Reply::Data(json!({"room":room})),Reply::Data(json!({"inspections":c.inspections})),Reply::Data(json!({"room":room})),Reply::Lost,Reply::Data(json!({"room":running}))]);c.base=origin;
 assert!(c.start_displayed(p.clone(),vec![],config).await.is_err());assert_eq!(c.ux1_view()["outcome"]["kind"],"Start");assert_eq!(c.ux1_view()["pending"],true);assert!(c.start_displayed(p,vec![],config).await.unwrap_err().contains("Previous lobby action"));c.ux1_retry().await.unwrap();assert_eq!(c.room.as_ref().unwrap().state.as_deref(),Some("running"));assert_eq!(c.ux1_view()["pending"],false);let calls=server.join().unwrap();assert_eq!(calls.len(),5);assert_eq!(calls[3],calls[4]);
});}
#[test]fn ux1_auth_refusal_after_lost_chat_does_not_prove_earlier_delivery_failed(){tauri::async_runtime::block_on(async{let mut c=fixture();let(origin,server)=network(vec![Reply::Lost,Reply::Error("UNAUTHENTICATED"),Reply::Data(json!({"chatMessages":[{"sequence":9,"text":"earlier message"}]}))]);c.base=origin;assert!(c.chat_send("earlier message".into()).await.is_err());assert_eq!(c.retry_chat().await.unwrap_err(),"UNAUTHENTICATED");assert!(c.chat_retry.is_some());assert!(c.chat_send("different intent".into()).await.is_err());c.retry_chat().await.unwrap();let calls=server.join().unwrap();assert_eq!(calls[0],calls[1]);assert_eq!(calls[1],calls[2]);});}
#[test]fn ux1_end_holds_local_authority_before_uncertain_reply_and_keeps_original(){tauri::async_runtime::block_on(async{
 for lc1 in [false,true]{let mut c=fixture();if lc1{c.enable_lc1();}let(origin,server)=network(vec![Reply::Lost]);c.base=origin;let revision=c.room.as_ref().unwrap().revision.unwrap();assert!(c.ux1_room_action("end",revision,None,None,None,None).await.is_err());assert!(c.ux1.original.as_ref().unwrap().request.end_run.is_some());assert_eq!(c.ux1_view()["pending"],true);if lc1{let p=c.pending.lock().unwrap();assert!(!p.as_ref().unwrap().release);assert!(p.as_ref().unwrap().authority_until<=Instant::now());}else{assert!(c.pending.lock().unwrap().is_none());}assert_eq!(server.join().unwrap().len(),1);}
});}

#[test]fn ux1_expired_outcome_requires_fresh_scoped_review_then_ack_sends_nothing(){tauri::async_runtime::block_on(async{
 let mut c=fixture();let mut room=c.room.clone().unwrap();room.revision=Some(2);let mut newer=room.clone();newer.revision=Some(3);let(origin,server)=network(vec![Reply::Lost,Reply::Error("EXPIRED"),Reply::Data(json!({"room":room})),Reply::Data(json!({"room":newer})),Reply::Data(json!({}))]);c.base=origin;let config=c.room.as_ref().unwrap().config.clone();assert!(c.ux1_room_action("configure",1,config.clone(),None,None,None).await.is_err());let id=c.ux1_view()["outcome"]["id"].as_str().unwrap().to_owned();assert_eq!(c.ux1_retry().await.unwrap_err(),"EXPIRED");assert_eq!(c.ux1_view()["outcome"]["id"],id);assert!(c.ux1.original.is_some());assert!(c.ux1_acknowledge_outcome("lobby","unreviewed").is_err());
 c.ux1_review_outcome("lobby",&id).await.unwrap();let stale=c.ux1_view()["outcome_review"]["token"].as_str().unwrap().to_owned();c.room.as_mut().unwrap().revision=Some(3);assert!(c.ux1_acknowledge_outcome("lobby",&stale).is_err());c.ux1_review_outcome("lobby",&id).await.unwrap();let token=c.ux1_view()["outcome_review"]["token"].as_str().unwrap().to_owned();c.ux1_acknowledge_outcome("lobby",&token).unwrap();assert!(c.ux1.original.is_none());assert_eq!(c.ux1_view()["acknowledged"]["lobby"]["id"],id);assert!(c.ux1_acknowledge_outcome("lobby",&token).is_err());c.ux1_room_action("configure",3,config,None,None,None).await.unwrap();let calls=server.join().unwrap();assert_eq!(calls.len(),5);assert_eq!(calls[0],calls[1]);assert!(calls[2]["roomGet"].is_object()&&calls[3]["roomGet"].is_object());assert_ne!(calls[4]["requestId"],calls[0]["requestId"]);
});}
#[test]fn ux1_review_auth_turnover_and_old_selection_cannot_unlock_or_replay(){tauri::async_runtime::block_on(async{
 let mut c=fixture();let(origin,server)=network(vec![Reply::Lost,Reply::Data(json!({}))]);c.base=origin;let config=c.room.as_ref().unwrap().config.clone();assert!(c.ux1_room_action("configure",1,config,None,None,None).await.is_err());c.ux1.original.as_mut().unwrap().until=Instant::now();let id=c.ux1_view()["outcome"]["id"].as_str().unwrap().to_owned();assert!(c.ux1_review_outcome("lobby","other-original").await.is_err());c.ux1_review_outcome("lobby",&id).await.unwrap();let token=c.ux1_view()["outcome_review"]["token"].as_str().unwrap().to_owned();c.desktop.as_mut().unwrap().epoch="new-session".into();assert!(c.ux1_acknowledge_outcome("lobby",&token).is_err());assert!(c.ux1_retry().await.is_err());assert_eq!(server.join().unwrap().len(),2);
});}
#[test]fn ux1_rules_and_recovery_expiry_keep_identity_and_review_only_reads(){tauri::async_runtime::block_on(async{
 let c1:Value=serde_json::from_str(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../packages/contracts/g3-c1/golden.json"))).unwrap();let c2:Value=serde_json::from_str(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../packages/contracts/g3-c2/golden.json"))).unwrap();
 for(path,reply)in [("/v3/c1/rpc",json!({"snapshot":c1["fixtures"][0]["json"]})),("/v3/c2/rpc",c2["fixtures"][2]["json"].clone()),("/v3/rejoin/rpc",json!({"participants":[]}))]{let mut c=fixture();let(origin,server)=network(vec![Reply::Data(json!({})),Reply::Data(reply)]);c.base=origin;c.ux1_prepare().unwrap();let request=json!({"requestId":uuid::Uuid::new_v4(),"review":{"immutable":"original"}});let id=request["requestId"].as_str().unwrap().to_owned();c.ux1.rule_original=Some((path.into(),request.clone(),Instant::now()));assert!(c.ux1_retry().await.is_err());assert_eq!(c.ux1.rule_original.as_ref().unwrap().1,request);c.ux1_review_outcome("lobby",&id).await.unwrap();let token=c.ux1_view()["outcome_review"]["token"].as_str().unwrap().to_owned();c.ux1_acknowledge_outcome("lobby",&token).unwrap();let calls=server.join().unwrap();assert_eq!(calls.len(),2);assert!(calls[1]["rulesGet"].is_object()||calls[1]["list"].is_object());assert_ne!(calls[1]["requestId"],id);}
});}
#[test]fn ux1_chat_expiry_preserves_original_until_history_review_and_ack(){tauri::async_runtime::block_on(async{
 let mut c=fixture();let(origin,server)=network(vec![Reply::Lost,Reply::Error("EXPIRED"),Reply::Data(json!({"chatMessages":[]})),Reply::Data(json!({"chatMessages":[{"sequence":8,"text":"separate send"}]}))]);c.base=origin;assert!(c.chat_send("unknown delivery".into()).await.is_err());let id=c.ux1_view()["chat_outcome"]["id"].as_str().unwrap().to_owned();assert_eq!(c.retry_chat().await.unwrap_err(),"EXPIRED");assert!(c.chat_send("edited draft".into()).await.is_err());c.ux1_review_outcome("chat",&id).await.unwrap();let token=c.ux1_view()["outcome_review"]["token"].as_str().unwrap().to_owned();c.ux1_acknowledge_outcome("chat",&token).unwrap();assert_eq!(c.chat_feedback["status"],"acknowledged_unknown");c.chat_send("separate send".into()).await.unwrap();let calls=server.join().unwrap();assert_eq!(calls.len(),4);assert_eq!(calls[0],calls[1]);assert!(calls[2]["chatList"].is_object());assert_ne!(calls[3]["requestId"],id);
});}
#[test]fn ux1_typed_actions_reject_wrong_lobby_and_untrusted_fields_without_touching_authority(){
 let mut c=fixture();let room=c.room.as_ref().unwrap().room_id.clone();let generation=c.generation.load(Ordering::Acquire);let world=c.pending.lock().unwrap().as_ref().unwrap().authority_until;
 assert!(c.ux1_guard_room(room.as_deref()).is_ok());assert!(c.ux1_guard_room(Some("other-lobby")).is_err());assert!(c.ux1_guard_room(None).is_err());let _=c.ux1_view();assert_eq!(c.generation.load(Ordering::Acquire),generation);assert_eq!(c.pending.lock().unwrap().as_ref().unwrap().authority_until,world);
 assert!(serde_json::from_value::<crate::next_app::Action>(json!({"action":"configure_lobby","token":"untrusted"})).is_err());assert!(serde_json::from_value::<crate::next_app::Action>(json!({"action":"raw_request","request":{}})).is_err());
 let before=serde_json::to_value(&c.room).unwrap();tauri::async_runtime::block_on(async{let action=serde_json::from_value(json!({"action":"set_lobby_policy","room":"other-lobby","revision":1,"policy":{"capacity":8}})).unwrap();assert!(crate::next_app::apply_action(&mut c,action).await.unwrap_err().contains("Lobby selection changed"));});assert_eq!(serde_json::to_value(&c.room).unwrap(),before);
}
#[test]fn ux1_mutation_lost_reply_reuses_exact_original_and_canonical_refusal_allows_correction(){tauri::async_runtime::block_on(async{
 let mut c=fixture();let(origin,server)=network(vec![Reply::Lost,Reply::Data(json!({})),Reply::Error("FORBIDDEN")]);c.base=origin;let revision=c.room.as_ref().unwrap().revision.unwrap();
 assert!(c.ux1_room_action("policy",revision,None,Some(wire::RoomPolicy{capacity:Some(8),..Default::default()}),None,None).await.is_err());let id=c.ux1.original.as_ref().unwrap().request.request_id.clone();assert!(c.ux1_view()["pending"]==true);
 assert!(c.ux1_room_action("policy",revision,None,Some(wire::RoomPolicy{capacity:Some(7),..Default::default()}),None,None).await.unwrap_err().contains("Previous lobby action"));
 c.ux1_retry().await.unwrap();assert!(c.ux1.original.is_none());assert!(c.ux1_room_action("policy",revision,None,Some(wire::RoomPolicy{capacity:Some(6),..Default::default()}),None,None).await.is_err());assert!(c.ux1.original.is_none());let calls=server.join().unwrap();assert_eq!(calls.len(),3);assert_eq!(calls[0],calls[1]);assert_eq!(calls[0]["requestId"],json!(id));assert_ne!(calls[0]["requestId"],calls[2]["requestId"]);
});}
#[test]fn ux1_expired_unknown_action_cannot_be_replaced_by_a_new_mutation(){tauri::async_runtime::block_on(async{
 let mut c=fixture();let(origin,server)=network(vec![Reply::Lost]);c.base=origin;let revision=c.room.as_ref().unwrap().revision.unwrap();let config=c.room.as_ref().unwrap().config.clone();assert!(c.ux1_room_action("configure",revision,config.clone(),None,None,None).await.is_err());c.ux1.original.as_mut().unwrap().until=Instant::now();assert!(c.ux1_retry().await.is_err());assert!(c.ux1.unconfirmed);assert!(c.ux1_room_action("configure",revision,config,None,None,None).await.is_err());assert_eq!(server.join().unwrap().len(),1);
});}
#[test]fn ux1_chat_receipt_is_exact_and_rate_refusal_preserves_the_right_to_edit(){tauri::async_runtime::block_on(async{
 let mut c=fixture();let(origin,server)=network(vec![Reply::Error("RATE_LIMITED"),Reply::Lost,Reply::Data(json!({"chatMessages":[{"sequence":7,"accountId":"fixture","text":"second"}]}))]);c.base=origin;
 assert_eq!(c.chat_send("first".into()).await.unwrap_err(),"RATE_LIMITED");assert!(c.chat_retry.is_none());assert_eq!(c.chat_feedback["status"],"failed");assert!(c.chat_send("second".into()).await.is_err());let id=c.chat_feedback["request"].clone();assert!(c.chat_retry.is_some());c.retry_chat().await.unwrap();assert_eq!(c.chat_feedback["request"],id);assert_eq!(c.chat_feedback["status"],"accepted");assert_eq!(c.chat_feedback["sequence"],7);let calls=server.join().unwrap();assert_eq!(calls[1],calls[2]);
});}
